/**
 * Router instance. Uses the file-based route tree generated by the
 * TanStack Router Vite plugin at `src/router/routeTree.gen.ts` (B-004
 * fix from the day-of-judgment).
 *
 * Day-of-judgment fix A-006: was `createMemoryHistory()` which kept
 * the URL frozen at "/" regardless of navigation. Replaced with
 * `createBrowserHistory()` so the browser address bar tracks the
 * active route. This unlocks refresh on any route, browser
 * back/forward, deep-link sharing, and the `redirect:` search param
 * that the auth guard relies on (PRD-v3 §4.1 item 11).
 *
 * `createBrowserHistory` and `createHashHistory` come from
 * `@tanstack/history` (re-exported by `@tanstack/vue-router`).
 * In production, the static host must serve `index.html` for unknown
 * paths (SPA fallback). Vite preview and most modern hosts
 * (Netlify, Vercel, Cloudflare Pages) do this by default.
 */
import { createRouter } from "@tanstack/vue-router";
import { createBrowserHistory } from "@tanstack/history";
import { routeTree } from "./routeTree.gen";

export const router = createRouter({
 routeTree,
 history: createBrowserHistory(),
 defaultPreload: "intent",
 defaultPreloadStaleTime: 0,
});
